""" Right rotate the number x by c bytes, for 64-bits numbers."""
def rightrotate_64(x: Any, c: Any) -> object {
    x &= 18446744073709551615;
    return (((x >> c) | (x << (64 - c))) & 18446744073709551615);
}

"""Takes a character from given string,
    shifts it secret times and return the
    character from lst depending on case of
    the taken character."""
def find_char(char: Any, secret: Any, lst: Any) -> object {
    pos = lst.index(char);
    offset = (pos + secret) % 26;
    ch = lst[offset];
    return ch;
}

"""
    Takes a string and breaks it into lines with <= n characters per line.

    Useful because psql queries have to have < 212 chars per line.
    """
def cut_lines_to_n(string: Any, n: Any = 200) -> object {
    out = [];
    lines = string.split("\n");
    for line in lines {
        newline = "";
        words = line.split(" ");
        for word in words {
            if ((len((newline + word)) + 1) > n) {
                out.append(newline.strip());
                newline = word;
            } else {
                newline += " " + word;
            }
        }
        out.append(newline);
    }
    return "\n".join(out);
}

