"""
    Converts the GitHub Link header to a dict:

    Example::

    >>> link2dict('<https://api.github.com/repos/sympy/sympy/pulls?page=2&state=closed>; rel="next",  <https://api.github.com/repos/sympy/sympy/pulls?page=21&state=closed>; rel="last"')
    {'last': 'https://api.github.com/repos/sympy/sympy/pulls?page=21&state=closed',  'next': 'https://api.github.com/repos/sympy/sympy/pulls?page=2&state=closed'}

    """
def _link2dict(l: Any) -> object {
    d = {};
    while True {
        i = l.find(";");
        assert (i != -1);
        assert (l[0] == "<");
        url = l[1:(i - 1)];
        assert (l[(i - 1)] == ">");
        assert (l[(i + 1):(i + 7)] == ' rel="');
        j = l.find('"', (i + 7));
        assert (j != -1);
        param = l[(i + 7):j];
        d[param] = url;
        if (len(l) == (j + 1)) {
            break;
        }
        assert (l[(j + 1)] == ",");
        j += 2;
        l = l[(j + 1):];
    }
    return d;
}

"""Get the specified build property from the build properties dictionary.

  Example property names are Chromium OS Version ('branch'), Chromium OS
  Version ('buildspec_version'), and GIT Revision ('git_revision').

  Args:
    build_properties: The properties dictionary for the build.
    property_name: The name of the build property.

  Returns:
    A string containing the property value.
  """
def _GetBuildProperty(build_properties: Any, property_name: Any) -> object {
    for property_list in build_properties {
        if (property_name in property_list) {
            property_value = property_list[1];
            break;
        }
    } else {
        property_value = None;
        print(('  Warning: Build properties has no %s property.' % property_name));
    }
    return property_value;
}
